morse.watch('div[aria-label="Tools"]', tools => {
  if (tools.querySelector('[data-morse-save]')) return;
  const board = document.getElementById('board');
  const btn = morse.el('button', {
    'aria-label': 'Save PNG',
    'data-morse-save': '',
    title: 'Save as PNG',
    text: '💾',
    style: 'width:38px;height:38px;margin:4px auto;border:0;border-radius:6px;background:transparent;cursor:pointer;font-size:18px;',
    on: {
      click: () => {
        board.toBlob(blob => {
          if (!blob) return;
          const a = morse.el('a', { href: URL.createObjectURL(blob), download: 'sketch.png' });
          document.body.appendChild(a);
          a.click();
          a.remove();
          setTimeout(() => URL.revokeObjectURL(a.href), 1000);
        }, 'image/png');
      }
    }
  });
  tools.appendChild(btn);
});

