results.js:
morse.watch("body > div.mn > h1", h1 => {
  if (h1.dataset.morseCsv) return;
  h1.dataset.morseCsv = "1";
  h1.style.display = "flex";
  h1.style.alignItems = "center";
  const btn = morse.el("button", { class: "morse-csv-btn", text: "Export to CSV" });
  btn.addEventListener("click", () => {
    const rows = morse.$$("body > div.mn > div.row2 > div.tbl table tr");
    const csv = rows.map(tr =>
      Array.from(tr.children)
        .map(c => '"' + c.textContent.trim().replace(/"/g, '""') + '"')
        .join(",")
    ).join("\n");
    const url = URL.createObjectURL(new Blob([csv], { type: "text/csv" }));
    const a = morse.el("a", { href: url, download: "orders.csv" });
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  });
  h1.appendChild(btn);
});

morse.watch("body > div.mn > h1", h1 => {
  const btn = morse.el("button", {
    class: "csv-export",
    text: "Export CSV",
    style: "margin-left:auto;font:inherit;font-size:13px;color:inherit;background:#fff;border:1px solid rgba(23,43,77,.2);border-radius:6px;padding:6px 12px;cursor:pointer",
    on: { click: () => {
      const table = morse.$("div.tbl table");
      if (!table) return morse.toast("No orders table found");
      const esc = v => `"${String(v).replace(/"/g, '""').trim()}"`;
      const lines = [...table.querySelectorAll("tr")].map(tr =>
        [...tr.children].map(c => esc(c.textContent)).join(","));
      const url = URL.createObjectURL(new Blob([lines.join("\n")], { type: "text/csv" }));
      const a = morse.el("a", { href: url, download: "orders.csv" });
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 1000);
      morse.toast("Exported " + (lines.length - 1) + " orders");
    }}
  });
  h1.appendChild(btn);
});

