morse.watch("div.tbl", el => {
  const h = el.querySelector("h3");
  if (!h || !h.textContent.includes("Recent orders")) return;
  const btn = morse.el("button", { class: "morse-csv-btn", text: "Export CSV" }, []);
  btn.addEventListener("click", () => {
    const rows = [...el.querySelectorAll("table tr")].map(tr =>
      [...tr.children].map(c => '"' + c.textContent.trim().replace(/"/g, '""') + '"').join(",")
    );
    const blob = new Blob([rows.join("\n")], { type: "text/csv" });
    const a = morse.el("a", { href: URL.createObjectURL(blob), download: "recent-orders.csv" });
    document.body.appendChild(a);
    a.click();
    a.remove();
    morse.toast("Exported " + Math.max(rows.length - 1, 0) + " orders");
  });
  el.insertBefore(btn, el.querySelector(".sc"));
});

