results.js:
morse.watch("div.sc table tbody td.am", el => {
  const raw = el.textContent.trim();
  const n = Number(raw);
  if (raw !== "" && !isNaN(n)) {
    el.textContent = "$" + n.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  }
});

morse.watch("div.sc table tbody td.am", el => {
  const raw = el.textContent.trim();
  if (!/^-?\d+(\.\d+)?$/.test(raw)) return;
  el.textContent = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" }).format(Number(raw));
}, { live: true });

morse.watch("div.tbl td.am", el => {
