morse.watch(".tbl", el => {
  if (el.querySelector(":scope > .morse-search")) return;
  const box = morse.el("input", {
    class: "morse-search",
    type: "search",
    placeholder: "Search orders…",
    "aria-label": "Search orders"
  });
  const sc = el.querySelector(":scope > .sc");
  if (!sc) return;
  el.insertBefore(box, sc);
  morse.on(box, "input", () => {
    const q = box.value.trim().toLowerCase();
    morse.$$(".tbl .sc tbody tr").forEach(tr => {
      const hit = !q || tr.textContent.toLowerCase().includes(q);
      tr.style.display = hit ? "" : "none";
    });
  });
});

