  if (el.querySelector(".morse-order-search")) return;
  const input = morse.el("input", {
    class: "morse-order-search",
    type: "search",
    placeholder: "Search orders…",
    "aria-label": "Search orders"
  });
  const h3 = el.querySelector(":scope > h3");
  if (h3) h3.after(input);
  else el.prepend(input);

  const filter = () => {
    const q = input.value.trim().toLowerCase();
    el.querySelectorAll(".sc tbody tr").forEach(tr => {
      const text = tr.textContent.toLowerCase();
      tr.style.display = !q || text.includes(q) ? "" : "none";
    });
  };
  morse.on(input, "input", filter);
});

