results.js:
morse.watch("div.tbl table", table => {
  const th = table.querySelector("thead th.am");
  if (!th || th.dataset.sortable) return;
  th.dataset.sortable = "1";
  th.style.cursor = "pointer";
  th.title = "Sort by amount";
  let asc = false;
  morse.on(th, "click", () => {
    asc = !asc;
    const tbody = table.querySelector("tbody");
    const rows = Array.from(tbody.querySelectorAll("tr"));
    const idx = Array.from(th.parentElement.children).indexOf(th);
    rows.sort((a, b) => {
      const va = parseFloat(a.children[idx]?.textContent.replace(/[^0-9.\-]/g, "")) || 0;
      const vb = parseFloat(b.children[idx]?.textContent.replace(/[^0-9.\-]/g, "")) || 0;
      return asc ? va - vb : vb - va;
    });
    rows.forEach(r => tbody.appendChild(r));
    morse.toast(asc ? "Sorted by amount, low to high" : "Sorted by amount, high to low");
  });
});

