results.js:
morse.watch("div.tbl table thead th.am", th => {
  morse.on(th, "click", () => {
    const tbody = th.closest("table").querySelector("tbody");
    if (!tbody) return;
    const dir = th.dataset.dir === "asc" ? -1 : 1;
    th.dataset.dir = dir === 1 ? "asc" : "desc";
    const val = r => parseFloat((r.querySelector("td.am")?.textContent || "").replace(/[^0-9.\-]/g, "")) || 0;
    [...tbody.querySelectorAll("tr")]
      .sort((a, b) => dir * (val(a) - val(b)))
      .forEach(r => tbody.appendChild(r));
  });
});

morse.watch("div.tbl table thead th.am", el => {
  if (el.dataset.sortReady) return;
  el.dataset.sortReady = "1";
  el.style.cursor = "pointer";
  el.title = "Click to sort by amount";
  let asc = false;
  morse.on(el, "click", () => {
    const table = el.closest("table");
    const tbody = table.querySelector("tbody");
    const idx = Array.from(el.parentElement.children).indexOf(el);
    const rows = Array.from(tbody.querySelectorAll("tr"));
    const num = s => parseFloat(String(s).replace(/[^0-9.\-]/g, "")) || 0;
    rows.sort((a, b) => {
      const av = num(a.children[idx]?.textContent);
      const bv = num(b.children[idx]?.textContent);
      return asc ? av - bv : bv - av;
    });
    asc = !asc;
    rows.forEach(r => tbody.appendChild(r));
    morse.toast(asc ? "Sorted: lowest first" : "Sorted: highest first");
  });
});

