    .reduce((s, td) => s + (parseFloat(td.textContent) || 0), 0)
    .toFixed(2);
  let foot = el.querySelector("tfoot.morse-total");
  if (!foot) {
    foot = morse.el("tfoot", { class: "morse-total" });
    el.appendChild(foot);
  }
  if (foot.dataset.v === total) return;
  foot.dataset.v = total;
  foot.replaceChildren(
    morse.el("tr", {},
      morse.el("td", { colspan: "4", text: "Total" }),
      morse.el("td", { class: "am", text: total })
    )
  );
