morse.on(document, "keydown", e => {
  if (e.metaKey || e.ctrlKey || e.altKey) return;
  const t = e.target;
  if (t && (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName))) return;
  if (e.key !== "j" && e.key !== "k") return;
  const list = [...morse.$$('section[aria-label="Message list"] [role="option"][data-i]')];
  if (!list.length) return;
  const cur = list.findIndex(r => r.getAttribute("aria-selected") === "true");
  const next = e.key === "j"
    ? Math.min(cur + 1, list.length - 1)
    : Math.max(cur - 1, 0);
  const row = list[next];
  e.preventDefault();
  row.click();
  row.scrollIntoView({ block: "nearest" });
});

morse.on(document, "keydown", e => {
  if (e.ctrlKey || e.metaKey || e.altKey) return;
  if (e.key !== "j" && e.key !== "k") return;
  const t = e.target;
  if (t instanceof Element && t.closest("input, textarea, select, [contenteditable='true']")) return;
  const rows = morse.$$('[role="option"][data-i]');
  if (!rows.length) return;
  const cur = rows.findIndex(r => r.getAttribute("aria-selected") === "true");
  const next = e.key === "j" ? cur + 1 : cur - 1;
  const target = rows[Math.min(rows.length - 1, Math.max(0, next))];
  e.preventDefault();
  target.click();
  target.scrollIntoView({ block: "nearest" });
});

let idx = -1;
const rows = () => morse.$$('section[aria-label="Message list"] div.r9[data-i]');
const move = d => {
  const list = rows();
  if (!list.length) return;
  const cur = list.findIndex(r => r.getAttribute('aria-selected') === 'true');
  const next = Math.min(list.length - 1, Math.max(0, (cur < 0 ? 0 : cur) + d));
  list[next].click();
  list[next].scrollIntoView({ block: 'nearest' });
};
morse.on(document, 'keydown', e => {
  const t = e.target;
  if (e.metaKey || e.ctrlKey || e.altKey) return;
  if (t && (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName))) return;
  if (e.key === 'j') { e.preventDefault(); move(1); }
  else if (e.key === 'k') { e.preventDefault(); move(-1); }
});
