morse.watch('div[aria-label="Formatting"]', bar => {
  if (bar.querySelector('.date-btn')) return;
  const today = new Date().toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
  const btn = morse.el('button', {
    class: 'date-btn',
    title: 'Insert today\'s date',
    text: 'Date',
    on: {
      click: () => {
        const box = document.querySelector('div[role="textbox"]');
        if (!box) { morse.toast('No editable note found'); return; }
        box.focus();
        const sel = window.getSelection();
        if (sel && sel.rangeCount) {
          const range = sel.getRangeAt(0);
          range.deleteContents();
          range.insertNode(document.createTextNode(today));
          range.collapse(false);
        } else {
          box.append(document.createTextNode(today));
        }
        box.dispatchEvent(new Event('input', { bubbles: true }));
      }
    }
  });
  bar.append(btn);
});

