morse.watch("div.pg > div.doc > div.in > div[role=\"textbox\"]", (ed) => {
  const countWords = (text) => {
    const t = text.trim();
    return t ? t.split(/\s+/).length : 0;
  };
  let label = ed.parentElement.querySelector(".wc_mod");
  if (!label) {
    label = morse.el("div", { class: "wc_mod" });
    ed.parentElement.insertBefore(label, ed);
  }
  const update = () => {
    const n = countWords(ed.textContent);
    label.textContent = n + (n === 1 ? " word" : " words");
  };
  update();
  morse.on(ed, "input", update);
});

morse.watch('div.pg > div.doc > div.in', el => {
  let badge = el.querySelector(':scope > .wc_live');
  if (!badge) {
    badge = morse.el('div', { class: 'wc_live', style: 'font-size:12px;color:rgb(155,154,151);margin-top:12px;' });
    el.appendChild(badge);
  }
  const box = el.querySelector('div[role="textbox"]');
  const update = () => {
    if (!box) return;
    const words = (box.textContent.trim().match(/\S+/g) || []).length;
    badge.textContent = words + (words === 1 ? ' word' : ' words');
  };
  update();
  morse.on(box, 'input', update);
});

