const toMarkdown = () => {
  const parts = morse.$$("section[aria-label='Conversation'] .msg[data-role]").map(m => {
    const who = m.dataset.role === "user" ? "You" : "Parley";
    const body = [...m.querySelectorAll("p")]
      .map(p => p.innerText.trim())
      .filter(Boolean)
      .join("\n\n") || m.innerText.trim();
    return `### ${who}\n\n${body}`;
  });
  return parts.join("\n\n---\n\n");
};

const copyMarkdown = () => {
  const md = toMarkdown();
  if (!md) { morse.toast("Nothing to copy yet"); return; }
  navigator.clipboard.writeText(md).then(
    () => morse.toast("Conversation copied as Markdown"),
    () => morse.toast("Copy failed")
  );
};

