results.js:
const priceOf = card => {
  for (const el of card.querySelectorAll("div, span")) {
    const m = el.textContent.trim().match(/^\$\s*([\d,]+(?:\.\d+)?)$/);
    if (m && el.children.length === 0) return parseFloat(m[1].replace(/,/g, ""));
  }
  return Infinity;
};

const sortByPrice = () => {
  const grid = morse.$("#__next > div:nth-of-type(2) > main > div:nth-of-type(2)");
  if (!grid) return;
  [...grid.children]
    .map(card => [priceOf(card), card])
    .sort((a, b) => a[0] - b[0])
    .forEach(([, card]) => grid.appendChild(card));
};

morse.watch("#__next > div:nth-of-type(2) > main > div:nth-of-type(1)", row => {
  if (row.querySelector("[data-morse-sort]")) return;
  row.appendChild(morse.el("button", {
    type: "button",
    text: "Sort by price: low to high",
    "data-morse-sort": "",
    style: "margin-left:auto;font:inherit;font-size:14px;padding:6px 12px;border:1px solid currentColor;border-radius:6px;background:transparent;color:inherit;cursor:pointer",
    on: { click: sortByPrice }
  }));
});

morse.watch("#__next > div:nth-of-type(2) > main", (main) => {
  if (main.querySelector(":scope > .morse-sort")) return;
  const bar = main.querySelector(":scope > div:nth-of-type(1)");
  const grid = main.querySelector(":scope > div:nth-of-type(2)");
  if (!bar || !grid) return;
  let ascending = false;
  const btn = morse.el("button", {
    class: "morse-sort",
    text: "Sort by price: low to high",
    style: "margin-left:auto;padding:6px 12px;font:inherit;font-size:14px;color:inherit;background:transparent;border:1px solid currentColor;border-radius:6px;cursor:pointer;opacity:0.85",
    on: {
      click: () => {
        const cards = Array.from(grid.children);
        const price = (card) => {
          const m = (card.textContent || "").match(/\$\s?([\d,]+(?:\.\d+)?)/);
          return m ? parseFloat(m[1].replace(/,/g, "")) : Infinity;
        };
        cards.sort((a, b) => ascending ? price(b) - price(a) : price(a) - price(b));
        cards.forEach((c) => grid.appendChild(c));
        ascending = !ascending;
        btn.textContent = ascending ? "Sort by price: high to low" : "Sort by price: low to high";
      },
    },
  });
  bar.appendChild(btn);
});

const GRID = "#__next > div:nth-of-type(2) > main > div:nth-of-type(2)";
const priceOf = el => {
  const m = el.textContent.match(/\$\s?(\d+(?:\.\d+)?)/);
  return m ? parseFloat(m[1]) : Infinity;
};

morse.watch("#__next > div:nth-of-type(2) > main > div:nth-of-type(1)", bar => {
  if (bar.querySelector("[data-sort-price]")) return;
  const btn = morse.el("button", {
    text: "Sort by price ↑",
    "data-sort-price": "",
    style: "margin-left:auto;font:inherit;font-size:14px;color:inherit;background:transparent;border:1px solid currentColor;border-radius:6px;padding:4px 10px;cursor:pointer;opacity:.8",
    on: {
      click: () => {
        const grid = morse.$(GRID);
        if (!grid) return;
        Array.from(grid.children)
          .sort((a, b) => priceOf(a) - priceOf(b))
          .forEach(item => grid.appendChild(item));
        morse.toast("Sorted by price, lowest first");
      }
    }
  });
  bar.appendChild(btn);
});

