results.js:
morse.watch('div[data-testid="player-controls"] .btns', el => {
  if (el.querySelector('.sleep-timer')) return;
  let minutes = 0;
  let timerId = null;
  const btn = morse.el('button', { class: 'sleep-timer', text: 'Sleep: off' });
  const video = null;
  const pause = () => {
    const pp = morse.$('button[data-testid="play-pause"]');
    if (pp && pp.getAttribute('aria-label') === 'Pause') pp.click();
  };
  const setLabel = () => {
    btn.textContent = minutes ? `Sleep: ${minutes}m` : 'Sleep: off';
  };
  btn.addEventListener('click', () => {
    const options = [0, 15, 30, 45, 60];
    minutes = options[(options.indexOf(minutes) + 1) % options.length];
    clearTimeout(timerId);
    timerId = null;
    if (minutes) timerId = setTimeout(() => { pause(); minutes = 0; setLabel(); timerId = null; }, minutes * 60000);
    setLabel();
    morse.toast(minutes ? `Music pauses in ${minutes} min` : 'Sleep timer off');
  });
  el.appendChild(btn);
});

morse.watch('[data-testid="player-controls"] .btns', (row) => {
  const steps = [0, 15, 30, 45, 60];
  let idx = 0;
  let deadline = 0;
  const btn = morse.el('button', {
    class: 'sleep-timer',
    'aria-label': 'Sleep timer',
    title: 'Sleep timer: click to set minutes',
    text: 'Zz',
    on: { click: () => {
      idx = (idx + 1) % steps.length;
      const mins = steps[idx];
      deadline = mins ? Date.now() + mins * 60000 : 0;
      btn.textContent = mins ? `Zz ${mins}m` : 'Zz';
      morse.toast(mins ? `Sleep in ${mins} min` : 'Sleep timer off');
    }}
  });
  row.appendChild(btn);
  morse.every(1000, () => {
    if (!deadline) return;
    if (Date.now() >= deadline) {
      deadline = 0;
      idx = 0;
      btn.textContent = 'Zz';
      const pp = morse.$('button[data-testid="play-pause"]');
      if (pp && pp.getAttribute('aria-label') === 'Pause') pp.click();
      morse.toast('Sleep timer: playback paused');
      return;
    }
    btn.textContent = `Zz ${Math.ceil((deadline - Date.now()) / 60000)}m`;
  });
});

morse.watch('[data-testid="player-controls"] .btns', (row) => {
  if (row.querySelector('[data-morse-sleep]')) return;
  const steps = [0, 15, 30, 60];
  let idx = 0, end = 0;
  const label = () => end
    ? '☾ ' + Math.max(1, Math.ceil((end - Date.now()) / 60000)) + 'm'
    : '☾ Off';
  const btn = morse.el('button', {
    'data-morse-sleep': '',
    'aria-label': 'Sleep timer',
    title: 'Sleep timer: click to cycle 15, 30, 60 minutes, then off',
    text: label(),
    style: 'font: inherit; color: inherit; background: none; border: 0; cursor: pointer; padding: 0 6px;',
    on: { click: () => {
      idx = (idx + 1) % steps.length;
      end = steps[idx] ? Date.now() + steps[idx] * 60000 : 0;
      btn.textContent = label();
      if (end) morse.toast('Playback will pause in ' + steps[idx] + ' minutes');
    }}
  });
  morse.every(1000, () => {
    if (!end) return;
    if (Date.now() >= end) {
      end = 0; idx = 0;
      const pause = morse.$('button[data-testid="play-pause"][aria-label="Pause"]');
      if (pause) pause.click();
      morse.toast('Sleep timer: playback paused');
    }
    btn.textContent = label();
  });
  row.appendChild(btn);
});

