morse.watch("#where", h => {
  const btn = morse.el("button", {
    type: "button",
    text: "All devices off",
    style: "margin-left:12px;padding:4px 10px;font:inherit;font-size:13px;color:currentColor;background:transparent;border:1px solid currentColor;border-radius:6px;cursor:pointer;vertical-align:middle",
    on: { click: () => {
      morse.$$("device-card").forEach(card => {
        card.shadowRoot?.querySelectorAll('button[aria-label$=": on"]').forEach(b => {
          if (!b.disabled) b.click();
        });
      });
      morse.toast("All devices turned off");
    }}
  });
  h.append(btn);
});

morse.watch("#where", h => {
  const btn = morse.el("button", {
    text: "All devices off",
    style: "display:inline-block;margin:0 0 12px;font:inherit;font-size:14px;padding:6px 14px;border-radius:8px;border:1px solid currentColor;background:transparent;color:inherit;cursor:pointer;",
    on: { click: () => {
      let n = 0;
      morse.$$("device-card").forEach(card => {
        card.shadowRoot?.querySelectorAll('button[aria-label$=": on"]:not([disabled])').forEach(b => { b.click(); n++; });
      });
      morse.toast(n ? `Turned off ${n} device${n === 1 ? "" : "s"}` : "Nothing was on");
    }}
  });
  btn.dataset.allOff = "1";
  h.after(btn);
});

